import 'package:flutter/material.dart';
import 'chat_room_screen.dart';
class PartyChatPreviewScreen extends StatelessWidget { const PartyChatPreviewScreen({super.key}); @override Widget build(BuildContext context) => Scaffold(backgroundColor: Colors.white, appBar: AppBar(title: const Text('여행 단톡방 미리보기', style: TextStyle(color: Colors.black, fontWeight: FontWeight.bold)), backgroundColor: Colors.white, elevation: 0, iconTheme: const IconThemeData(color: Colors.black)), body: Column(children: [Container(padding: const EdgeInsets.all(16), color: Colors.grey.shade50, child: const Row(children: [Icon(Icons.info_outline, color: Colors.grey, size: 16), SizedBox(width: 8), Expanded(child: Text('이 단톡방은 여행 확정 후 활성화됩니다. (미리보기 3개)', style: TextStyle(color: Colors.grey, fontSize: 12)))])), Expanded(child: ListView(padding: const EdgeInsets.all(16), children: [_preview('유스', '안녕하세요 하하하 여행 기대되어요!'), _preview('지은', '저도요! 목포 낙지 좋아하신분?'), _preview('수현', '네다바다 샾하는거 좋아해요 ❤️')])), SafeArea(child: Padding(padding: const EdgeInsets.all(16), child: ElevatedButton(onPressed: () => Navigator.push(context, MaterialPageRoute(builder: (_) => const ChatRoomScreen(roomName: '목포 당일치기 단톡방'))), style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFFFF3B30), minimumSize: const Size(double.infinity, 56), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16))), child: const Text('단톡방 입장하기', style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 16))))) ]));
  static Widget _preview(String name, String msg) => ListTile(leading: CircleAvatar(backgroundColor: const Color(0xFFFF3B30).withOpacity(0.2), child: Text(name[0], style: const TextStyle(color: Color(0xFFFF3B30), fontWeight: FontWeight.bold))), title: Text(name, style: const TextStyle(fontWeight: FontWeight.bold)), subtitle: Text(msg, overflow: TextOverflow.ellipsis));
}
